VALUES (137720, 'tt14741708', NULL, 'Frankelda''s Book of Spooks', 'Los sustos ocultos de Frankelda', 'tv', 2021, 'https://image.tmdb.org/t/p/w500/l7joGj61QSDC2jsIOgnUVftoiu2.jpg', 'https://image.tmdb.org/t/p/original/nZeNGxCLzQTDLjMdRrgDYsnzCWv.jpg', 'Frankelda, a mysterious phantom writer, with the help of her grumpy enchanted book, tells terrifying stories in which girls and boys have encounters with monsters that will make them face their deepest fears.', NULL, NULL, 2.4307, 8.6, 0, 9.51, '2026-10-10 20:20:08', '2026-10-10 20:20:08')
