VALUES (11828, 'tt0097289', NULL, 'Erik the Viking', 'Erik the Viking', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/tRaNvLehJf0OVsBexo4u4NRKLJ4.jpg', 'https://image.tmdb.org/t/p/original/rZlMfuYPGxtyxOUzNLLF4iyM0lF.jpg', 'Erik the Viking gathers warriors from his village and sets out on a dangerous journey to Valhalla, to ask the gods to end the Age of Ragnorok and allow his people to see sunlight again. A Pythonesque satire of Viking life.', NULL, NULL, 6.0101, 5.9, 0, 10.02, '2026-10-10 20:20:08', '2026-10-10 20:20:08')
