VALUES (5961, 'tt0083922', NULL, 'Fanny and Alexander', 'Fanny och Alexander', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/q8jlA3Wc1Z987hNKRFA44g5OugC.jpg', 'https://image.tmdb.org/t/p/original/8reX3CMog1QHqGoym2Esvuk5MnK.jpg', 'As children in the loving Ekdahl family, Fanny and Alexander enjoy a happy life with their parents, who run a theater company. After their father dies unexpectedly, however, the siblings end up in a joyless home when their mother, Emilie, marries a stern bishop. The bleak situation gradually grows worse as the bishop becomes more controlling, but dedicated relatives make a valiant attempt to aid Emilie, Fanny and Alexander.', NULL, NULL, 6.2217, 7.8, 0, 11.56, '2026-10-10 20:20:08', '2026-10-10 20:20:08')
