VALUES (84290, 'tt2011953', NULL, 'Keep the Lights On', 'Keep the Lights On', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/xuY4WOU8PHEFjRpPxNQMVyLNfPs.jpg', 'https://image.tmdb.org/t/p/original/dRTa5iJHxqPmhsdVgJnnrqlZEtV.jpg', 'In 1997 New York City, filmmaker Erik bonds with closeted lawyer Paul after a one-night fling. As their relationship evolves through dysfunctional patterns, Erik struggles to negotiate his own boundaries while being true to himself.', NULL, NULL, 2.307, 5.7, 0, 10.51, '2026-10-10 20:20:08', '2026-10-10 20:20:08')
