VALUES (17539, 'tt0137386', NULL, 'Billy''s Hollywood Screen Kiss', 'Billy''s Hollywood Screen Kiss', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/dUj3KciCFdOPnyavPzhYbbpIHv5.jpg', 'https://image.tmdb.org/t/p/original/6gedxusAaVYNARRneJfpGGhQlT6.jpg', 'Billy Collier is a photographer working on a series of pictures featuring recreations of movie kisses, with drag queens playing the female roles. For his male model, he hires Gabriel, a young waiter on whom he has developed a serious crush. While Billy is openly gay, Gabriel says that he is straight and even claims to have a girlfriend. However, as they spend more time together and grow closer, Billy becomes increasingly unsure that this is true.', NULL, NULL, 1.7096, 5.9, 0, 10.51, '2026-10-10 20:20:08', '2026-10-10 20:20:08')
