VALUES (1566163, NULL, NULL, 'Flirt', 'Flirt', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/eVNq2MJoywSBlxe68NcDFUHViBb.jpg', 'https://image.tmdb.org/t/p/original/zCsg53gjBsc5tXvqKjTsYZOJvIY.jpg', 'Flirt is a romantic-comedy-thriller centered around a young man (portrayed by Chandan Kumar) whose life intertwines with love, friendship and emotional chaos. The film explores relationships, romance and unexpected twists in an entertaining blend of humour, drama and heart. Performances especially by the lead pair are highlighted as the film’s strongest aspect.', NULL, NULL, 1.937, 0.0, 0, 10.01, '2026-10-10 20:20:08', '2026-10-10 20:20:08')
