VALUES (17447, 'tt0113464', NULL, 'Jeffrey', 'Jeffrey', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/cacIqtIkUaD5xYqUUN1J7qJjciQ.jpg', 'https://image.tmdb.org/t/p/original/8dCgk9uer8DvMHKdC7wcyzPTwiA.jpg', 'Jeffrey, a gay man living in New York City with an overwhelming fear of contracting AIDS, concludes that being celibate is the only option to protect himself. As fate would have it, shortly after his declaration of a sex-free existence, he meets the handsome Steve Howard, his dream man -- except for his HIV-positive status. Facing this dilemma, Jeffrey turns to his best friend and an outrageous priest for guidance.', NULL, NULL, 2.3048, 6.2, 0, 10.01, '2026-10-10 20:20:08', '2026-10-10 20:20:08')
