VALUES (48231, 'tt1571222', NULL, 'A Dangerous Method', 'A Dangerous Method', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/7TPYtzq9ABkfED1JB0tRASamL4z.jpg', 'https://image.tmdb.org/t/p/original/iGMz1vJEVZNdBafpE7vrHIj1Quo.jpg', 'Seduced by the challenge of an impossible case, the driven Dr. Carl Jung takes the unbalanced yet beautiful Sabina Spielrein as his patient. Jung’s weapon is the method of his master, the renowned Sigmund Freud. Both men fall under Sabina’s spell.', NULL, NULL, 6.1468, 6.35, 0, 10.01, '2026-10-10 20:20:08', '2026-10-10 20:20:08')
