VALUES (44826, 'tt0970179', NULL, 'Hugo', 'Hugo', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/1dxRq3o3l3bVWNRvvSb7rRf68qp.jpg', 'https://image.tmdb.org/t/p/original/Aj81Gu3u1a64qXFOLDuF5gdxyy0.jpg', 'Orphaned and alone except for an uncle, Hugo Cabret lives in the walls of a train station in 1930s Paris. Hugo''s job is to oil and maintain the station''s clocks, but to him, his more important task is to protect a broken automaton and notebook left to him by his late father. Accompanied by the goddaughter of an embittered toy merchant, Hugo embarks on a quest to solve the mystery of the automaton and find a place he can call home.', NULL, NULL, 6.2029, 7.175, 0, 2.11935294117647075e+01, '2026-07-15 12:01:52', '2026-10-10 20:20:08')
