VALUES (7451, 'tt0295701', NULL, 'xXx', 'xXx', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/xeEw3eLeSFmJgXZzmF2Efww0q3s.jpg', 'https://image.tmdb.org/t/p/original/qwK9soQmmJ7kRdjLZVXblw3g7AQ.jpg', 'Xander Cage is your standard adrenaline junkie with no fear and a lousy attitude. When the US Government "recruits" him to go on a mission, he''s not exactly thrilled. His mission: to gather information on an organization that may just be planning the destruction of the world, led by the nihilistic Yorgi.', NULL, NULL, 16.7304, 5.989, 0, 18.315, '2026-07-15 12:01:52', '2026-10-10 20:20:08')
