VALUES (9540, 'tt0094964', NULL, 'Dead Ringers', 'Dead Ringers', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/ofXwDfM8uYAaftD7cBPcIWdCpMn.jpg', 'https://image.tmdb.org/t/p/original/n3QtJ6tqE0fnf4Qaxb0iujBk0lH.jpg', 'Elliot, a successful gynecologist, works at the same practice as his identical twin, Beverly. Elliot is attracted to many of his patients and has affairs with them. When he inevitably loses interest, he will give the woman over to Beverly, the meeker of the two, without the woman knowing the difference. Beverly falls hard for one of the patients, Claire, but when she inadvertently deceives him, he slips into a state of madness.', NULL, NULL, 5.4696, 7.116, 0, 1.91113333333333343e+01, '2026-07-20 04:02:06', '2026-10-10 20:20:08')
