VALUES (11005, 'tt0099077', NULL, 'Awakenings', 'Awakenings', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/9gztZXuHLG6AJ0fgqGd7Q43cWRI.jpg', 'https://image.tmdb.org/t/p/original/tRKTlMoTsAhYpuq19V8Wk3RFY4O.jpg', 'Dr. Malcolm Sayer, a shy research physician, uses an experimental drug to "awaken" the catatonic victims of a rare disease. Leonard is the first patient to receive the controversial treatment. His awakening, filled with awe and enthusiasm, proves a rebirth for Sayer too, as the exuberant patient reveals life''s simple but unutterably sweet pleasures to the introverted doctor.', NULL, NULL, 7.1383, 7.788, 0, 9.35, '2026-08-03 14:31:56', '2026-10-10 20:20:08')
