VALUES (17897, 'tt0071569', NULL, 'The Golden Voyage of Sinbad', 'The Golden Voyage of Sinbad', 'movie', 1973, 'https://image.tmdb.org/t/p/w500/2DQPnuAjD7H4ae6BeBAVhu9RLWa.jpg', 'https://image.tmdb.org/t/p/original/izHLxrSRlATwwHFGe6eKQobGWlb.jpg', 'Sinbad and his crew intercept a homunculus carrying a golden tablet. Koura, the creator of the homunculus and practitioner of evil magic, wants the tablet back and pursues Sinbad. Meanwhile, Sinbad meets the Vizier who has another part of the interlocking golden map, and they mount a quest across the seas to solve the riddle of the map.', NULL, NULL, 4.016, 6.725, 0, 9.51, '2026-08-09 02:29:31', '2026-10-10 20:20:08')
