VALUES (568091, 'tt4332232', NULL, 'Fractured', 'Fractured', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/paZNRffT3kUckuRFKbeDBuX1YcZ.jpg', 'https://image.tmdb.org/t/p/original/6y4748yU4dnrI7jF2loGscmiVXQ.jpg', 'Driving cross-country, Ray and his wife and daughter stop at a highway rest area where his daughter falls and breaks her arm. After a frantic rush to the hospital and a clash with the check-in nurse, Ray is finally able to get her to a doctor. While the wife and daughter go downstairs for an MRI, Ray, exhausted, passes out in a chair in the lobby. Upon waking up, they have no record or knowledge of Ray''s family ever being checked in.', NULL, NULL, 5.7948, 6.768, 0, 12.6, '2026-08-22 01:37:44', '2026-10-10 20:20:08')
