VALUES (17979, 'tt1067106', NULL, 'A Christmas Carol', 'A Christmas Carol', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/xNwlAIdx1Ln28GRiQttUP9Gojy2.jpg', 'https://image.tmdb.org/t/p/original/uocpNfrP0Vvnf2UxykXuIR1HNUd.jpg', 'Miser Ebenezer Scrooge is awakened on Christmas Eve by spirits who reveal to him his own miserable existence, what opportunities he wasted in his youth, his current cruelties, and the dire fate that awaits him if he does not change his ways. Scrooge is faced with his own story of growing bitterness and meanness, and must decide what his own future will hold: death or redemption.', NULL, NULL, 11.804, 6.91, 0, 6.51, '2026-08-23 01:42:21', '2026-10-10 20:20:08')
