VALUES (454889, 'tt6053440', NULL, 'Princess Cyd', 'Princess Cyd', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/7ZhF8acObc0R5tIETl7doRO1Bac.jpg', 'https://image.tmdb.org/t/p/original/9morAQCYVynv69UQDV4iVkUgOHN.jpg', 'High school athlete Cyd Loughlin lives alone with her depressive father in South Carolina, perpetually longing to get away from it all. When her aunt, famous novelist Miranda Ruth, agrees to host her for a few weeks during the summer, Cyd jumps at the opportunity. While there, she falls for a girl in the neighborhood, even as she and her aunt gently challenge each other in the realms of sex and spirit.', NULL, NULL, 1.1384, 6.57, 0, 6.22, '2026-08-28 09:15:01', '2026-10-10 20:20:08')
